        .status_bar_yellow {
            height: 0;
            width: 100%;
            background: linear-gradient(215deg, #fcad13, #ffdb51)
        }
        
        .status_bar_yellow::after {
            content: "";
            position: fixed;
            top: 0;
            z-index: 999999;
            height: 0;
            width: 100%;
            background: linear-gradient(215deg, #fcad13, #ffdb51)
        }
        
        .status_bar {
            height: 0;
            width: 100%;
            background: #fff
        }
        
        .status_bar::after {
            content: "";
            position: fixed;
            top: 0;
            z-index: 999999;
            height: 0;
            width: 100%;
            background: #fff
        }
        
        .blur {
            /* Chrome, Opera */
            -webkit-filter: blur(5px);
            -moz-filter: blur(5px);
            -ms-filter: blur(5px);
            filter: blur(5px);
            height: 100vh
        }
        
        .u-navbar-content-title {
            font-family: PingFangSC-Regular, PingFang SC;
            font-weight: 400;
            font-size: 16px!important;
            color: #000
        }
        
        .mt-10 {
            margin-top: 5px
        }
        
        .mb-10 {
            margin-bottom: 5px
        }
        
        .mt-4 {
            margin-top: 2px
        }
        
