        }
        
        .px-global-mark {
            display: none;
            position: fixed;
            z-index: 999999999;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            background-color: rgba(0, 0, 0, .5);
            align-items: center;
            justify-content: center
        }
        
        .px-global-popup {
            background-color: #fff;
            width: 330px;
            min-height: 102px;
            border-radius: 20px;
            box-shadow: 0 0 20px -2px rgba(0, 0, 0, .3);
            padding: 20px 0
        }
        
        .px-global-popup .title {
            text-align: center;
            font-size: 16px;
            font-family: PingFang SC-Semibold, PingFang SC;
            font-weight: 600;
            color: #333;
            margin-bottom: 15px
        }
        
        .px-global-popup .content {
            margin: 0 25px;
            font-size: 14px;
            font-family: PingFang SC-Semibold, PingFang SC;
            font-weight: 400;
            color: #999;
            text-align: center
        }
        
        .px-global-popup .but-group {
            display: flex;
            align-items: center;
            justify-content: center;
            margin-top: 15px;
            padding: 0 20px
        }
        
        .px-global-popup .but-group .cancel-btn {
            display: none;
            flex: 1;
            min-width: 100px;
            max-width: 150px;
            height: 40px;
            border: 1px solid #f08c2b;
            border-radius: 10px;
            font-size: 16px;
            font-family: PingFang SC-Semibold, PingFang SC;
            font-weight: 500;
            text-align: center;
            line-height: 40px;
            margin-right: 10px;
            color: #f08c2b
        }
        
        .px-global-popup .but-group .confirm-btn {
            flex: 1;
            min-width: 100px;
            max-width: 150px;
            height: 40px;
            background: #f08c2b;
            border: 1px solid #f08c2b;
            border-radius: 10px;
            font-size: 16px;
            font-family: PingFang SC-Semibold, PingFang SC;
            font-weight: 500;
            text-align: center;
            line-height: 40px;
            color: #fff
        }
        
        .px-global-mark.show {
            display: flex;
            -webkit-animation-name: show;
            animation-name: show;
            -webkit-animation-duration: .2s;
            animation-duration: .2s;
            -webkit-animation-fill-mode: forwards;
            animation-fill-mode: forwards
        }
        
        @-webkit-keyframes show {
            from {
                transition: scale(1.5, 1.5);
                opacity: 0
            }
            to {
                transition: scale(1, 1);
                opacity: 1
            }
        }
        
        @keyframes show {
            from {
                transition: scale(1.5, 1.5);
                opacity: 0
            }
            to {
                transition: scale(1, 1);
                opacity: 1
            }
        }
        
        .px-global-mark.hide {
            -webkit-animation-name: hide;
            animation-name: hide;
            -webkit-animation-duration: .2s;
            animation-duration: .2s;
            -webkit-animation-fill-mode: forwards;
            animation-fill-mode: forwards
        }
        
        @-webkit-keyframes hide {
            from {
                transition: scale(1, 1);
                opacity: 1
            }
            to {
                transition: scale(1.5, 1.5);
                opacity: 0;
                display: none
            }
        }
        
        @keyframes hide {
            from {
                transition: scale(1, 1);
                opacity: 1
            }
            to {
                transition: scale(1.5, 1.5);
                opacity: 0;
                display: none
            }
        }
