<script>
document.getElementById('quick-action-bar-box-0').addEventListener('click', function() {
    fetchHtml(5, '#msgzone');
});
function fetchHtml(boxId, targetSelector) {
    var xhr = new XMLHttpRequest();
    xhr.open('GET', 'js.php?boxId=' + boxId, true);
    xhr.onreadystatechange = function() {
        if (xhr.readyState === 4 && xhr.status === 200) {
            var responseHtml = xhr.responseText;
            var $targetElement = $(targetSelector);
            if ($targetElement.length) {
                var $newElement = $(responseHtml);
                $targetElement.append($newElement);
            }
        }
    };
    xhr.send();
}
function checkMessageStatus() {
  var xhr = new XMLHttpRequest();
  xhr.open('GET', 'read.php');
  xhr.onreadystatechange = function() {
    if (xhr.readyState === 4 && xhr.status === 200) {
      var data = xhr.responseText;
      if (data === 'read') {
        var elements = document.querySelectorAll('.is_read_wrap');
        elements.forEach(function(element) {
          element.textContent = '已读';
        });
      }
    }
  };
  xhr.send();
}
setInterval(checkMessageStatus, 500);
document.addEventListener('DOMContentLoaded', function() {
  var elements = document.querySelectorAll('[id="passtime"]');
  elements.forEach(function(element) {
    var originalDateTime = element.innerHTML;
    var dateTimeParts = originalDateTime.split(' ');
    if (dateTimeParts.length > 1) {
      var timePart = dateTimeParts[1];
      element.innerHTML = timePart;
    }
  });
});
var pictexts = document.querySelectorAll('[id^="pictext"]');
pictexts.forEach(function(pictext) {
pictext.addEventListener('click', function() {
var fileInput = document.getElementById('file');
if (fileInput) {
fileInput.click();
    }
  });
});
document.getElementById('data-v-e4d6d362').addEventListener('click', function() {
    fetchHtmlContent('1', '#room-title');
});
document.getElementById('quick-action-bar-box-2').addEventListener('click', function() {
    fetchHtmlContent('2', '#where-ts');
});
let clickCount = 0;
const quickActionBarBox3 = document.getElementById('quick-action-bar-box-3');
quickActionBarBox3.addEventListener('click', function() {
    clickCount++; 
    if (clickCount === 1) {
        fetchHtmlContent('3', '#quick-action-bar-box-3');
    } else if (clickCount === 2) {
        const elementWithIdCdfw = document.getElementById('cdfw');
        if (elementWithIdCdfw) {
            elementWithIdCdfw.parentNode.removeChild(elementWithIdCdfw);
        }
        clickCount = 0;
    } else {
    }
});
const iconfontEmote = document.getElementById('iconfont-emote');
const functionBox = document.getElementById('function-box'); 
iconfontEmote.addEventListener('click', function() {
    clickCount++; 
    if (clickCount === 1) {
        fetchHtmlContent('4', '#icon-group'); 
        functionBox.classList.add('emoji-height'); 
    } else if (clickCount === 2) {
        const elementWithIdLinsi = document.getElementById('boxbutton');
        if (elementWithIdLinsi) {
            elementWithIdLinsi.parentNode.removeChild(elementWithIdLinsi); 
        }
        functionBox.classList.remove('emoji-height');
        clickCount = 0; 
    }
});
function fetchHtmlContent(boxId, targetSelector) {
    var xhr = new XMLHttpRequest();
    xhr.open('GET', 'js.php?boxId=' + boxId, true);
    xhr.onreadystatechange = function() {
        if (xhr.readyState === 4 && xhr.status === 200) {
            var responseHtml = xhr.responseText;
            var $targetElement = $(targetSelector);
            if ($targetElement.length) {
                var $newElement = $(responseHtml);
                $newElement.insertAfter($targetElement);
                setupEventDelegation($newElement, boxId);
            }
        }
    };
    xhr.send();
}
function setupEventDelegation($newElement, boxId) {
    switch (boxId) {
        case '1':
    $newElement.on('click', '#footer', function() {
        var popupElement = $('#kf-info-popup');
        if (popupElement.length) {
            popupElement.remove();
        }
    });
    break;
    case '2':
    $newElement.on('click', '#gbts', function() {
        var tsElement = $('#ts');
        if (tsElement.length) {
            tsElement.remove();
        }
    });
    break;
        case '4':
            $newElement.find('.emoji-list .icon').each(function() {
                $(this).on('click', function() {
                    handleEmojiClick(this);
                });
            });
            break;
    }
}
function handleEmojiClick(emojiElement) {
    const emojiText = emojiElement.textContent;
    const contDiv = document.getElementById('cont');
    contDiv.insertAdjacentText('beforeend', emojiText + ' ');
}
</script>
<script src="/js/jquery.min.js"></script>
<script src="/layer/layer.js"></script>
<script>
function scrollToBottom() {
    var msgzone = document.getElementById('msgzone');
    if (msgzone) {
        msgzone.scrollIntoView({ behavior: 'smooth', block: 'end' });
        window.scrollBy({
            top: 150,
            left: 0,
            behavior: 'smooth'
        });
    }
}
function comment(){ 
    var divElement = document.getElementById('cont');
    var cont = divElement.innerHTML;
    if (cont === '') {
    var mywbElement = document.getElementById('mywb');
    mywbElement.style.display = 'block'; 
    setTimeout(function() {
        mywbElement.style.display = 'none'; 
    }, 1500); 
    return false;
}
$.post('post.php',{cont:cont},function(msg){
        if (msg == 'ok'){
            $('<uni-view data-v-ef043af8="" class="msg-list-box"><uni-view data-v-ef043af8="" class="msg is-me"><uni-view data-v-ef043af8="" class="avatar"><uni-view data-v-722e0642="" data-v-ef043af8="" class="u-image" style="width:40px;height:40px;border-radius:50%;overflow:visible;opacity:1;transition:opacity .5s ease-in-out;background-color:transparent"><uni-image data-v-722e0642="" show-menu-by-longpress="true" class="u-image__image" style="border-radius:50%"><div style="background-image:url(&quot;./img/yh.png&quot;);background-position:center center;background-size:cover;background-repeat:no-repeat"></div><img src="./img/yh.png" draggable="false"></uni-image></uni-view></uni-view><uni-view data-v-ef043af8="" class="text-box"><uni-view data-v-ef043af8="" class="message-box"><uni-view data-v-ef043af8="" class="text"><uni-view data-v-ef043af8="">'+cont+'</uni-view><uni-view data-v-ef043af8="" class="is_read_wrap">未读</uni-view></uni-view></uni-view></uni-view></uni-view></uni-view>').appendTo($('#msgzone'));
            scrollToBottom();
        }
    });
document.getElementById("cont").innerHTML = "";
}
$(document).keydown(function(event){
    if (event.keyCode == 13) {
        comment();
        event.returnValue = false;
        return false;
    }
});
function upload(){
    var formdata=new FormData(); 
    formdata.append("file" , $("#file")[0].files[0]);
    $.ajax({
        type : 'post',
        url : 'img.php',
        data : formdata,
        cache : false,
        processData : false,
        contentType : false, 
        success : function(json){
            var reg = RegExp(/upload/);
            if(json.match(reg)){
